1	export type QuoteResult = { premium: number };
2	
3	export type ClaimResult = { payout: number; remainingCap: number };
4	
5	export type StepResult = QuoteResult | ClaimResult;
6	
7	export type ScenarioResults = { results: StepResult[] };
8	
9	const PROCESSING_FEE = 5;
10	
11	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
12	
13	const LOYALTY_DISCOUNT_RATE = 0.2;
14	
15	const LOYALTY_THRESHOLD_YEARS = 2;
16	
17	const FOLLOW_UP_CONTRACT_DISCOUNT_RATE = 0.15;
18	
19	// One catalogue entry per insurable item type. Premium and insurance value are
20	// two facts about the same thing, so they live together: an item type either is
21	// in the catalogue with both, or is unknown.
22	type CatalogueEntry = { basePremium: number; insuranceValue: number };
23	
24	const ITEM_CATALOGUE: Record<string, CatalogueEntry> = {
25	  sword: { basePremium: 100, insuranceValue: 1000 },
26	  amulet: { basePremium: 60, insuranceValue: 600 },
27	  staff: { basePremium: 80, insuranceValue: 800 },
28	  potion: { basePremium: 40, insuranceValue: 400 },
29	  rune: { basePremium: 25, insuranceValue: 250 },
30	  moonstone: { basePremium: 25, insuranceValue: 250 },
31	};
32	
33	// The catalogue is the single place that decides whether an item type exists,
34	// so an unknown type fails here, by name, rather than as a stray TypeError
35	// somewhere downstream.
36	const catalogueEntryOf = (type: string): CatalogueEntry => {
37	  const entry = ITEM_CATALOGUE[type];
38	  if (entry === undefined) {
39	    throw new Error(`Unknown item type: ${type}`);
40	  }
41	  return entry;
42	};
43	
44	const basePremiumOf = (type: string): number =>
45	  catalogueEntryOf(type).basePremium;
46	
47	const insuranceValueOf = (type: string): number =>
48	  catalogueEntryOf(type).insuranceValue;
49	
50	type Item = { type: string; cursed?: boolean; enchantment?: number };
51	
52	// Steps are discriminated by `op`: a quote carries the items to insure, a claim
53	// carries damage entries against a policy an earlier quote step created.
54	type QuoteStep = { op: "quote"; items: Item[] };
55	
56	type Damage = { itemType: string; amount: number };
57	
58	type Incident = { cause: string; damages: Damage[] };
59	
60	type ClaimStep = { op: "claim"; policy: number; incident: Incident };
61	
62	type Step = QuoteStep | ClaimStep;
63	
64	// Scenarios arrive as parsed JSON (from the CLI, and from object literals in
65	// the spec whose `op` widens to `string`), so the boundary type is deliberately
66	// wider than `Step`. Narrowing happens once, in `runStep`.
67	type StepInput = {
68	  op: string;
69	  items?: Item[];
70	  policy?: number;
71	  incident?: Incident;
72	};
73	
74	const isQuoteStep = (step: StepInput): step is QuoteStep =>
75	  step.op === "quote" && step.items !== undefined;
76	
77	const isClaimStep = (step: StepInput): step is ClaimStep =>
78	  step.op === "claim" && step.incident !== undefined && step.policy !== undefined;
79	
80	type Customer = { yearsWithMHPCO: number };
81	
82	type Scenario = { customer: Customer; steps: StepInput[] };
83	
84	const BLOCK_SIZE = 3;
85	
86	// A block is exactly BLOCK_SIZE components of the same type, priced as a unit.
87	// Exactly: 4 runes are not a block (4 x 25), and 2 runes + 1 moonstone is not
88	// a block either — "alike" means the same type, not the same family.
89	const BLOCK_BASE_PREMIUM = 60;
90	
91	const COMPONENT_TYPES = new Set(["rune", "moonstone"]);
92	
93	const countByType = (items: Item[]): Map<string, number> =>
94	  items.reduce(
95	    (counts, item) => counts.set(item.type, (counts.get(item.type) ?? 0) + 1),
96	    new Map<string, number>(),
97	  );
98	
99	const isBlock = (type: string, count: number): boolean =>
100	  COMPONENT_TYPES.has(type) && count === BLOCK_SIZE;
101	
102	const groupBasePremium = (type: string, count: number): number =>
103	  isBlock(type, count) ? BLOCK_BASE_PREMIUM : count * basePremiumOf(type);
104	
105	const sum = (numbers: number[]): number =>
106	  numbers.reduce((total, value) => total + value, 0);
107	
108	const policyBasePremium = (items: Item[]): number =>
109	  sum(
110	    [...countByType(items)].map(([type, count]) =>
111	      groupBasePremium(type, count),
112	    ),
113	  );
114	
115	const CURSE_SURCHARGE_RATE = 0.5;
116	
117	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
118	
119	const HIGH_ENCHANTMENT_THRESHOLD = 5;
120	
121	const isCursed = (item: Item): boolean => item.cursed === true;
122	
123	const isHighlyEnchanted = (item: Item): boolean =>
124	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD;
125	
126	// Both surcharges can apply to the same item, so the rates add.
127	const itemSurchargeRate = (item: Item): number =>
128	  (isCursed(item) ? CURSE_SURCHARGE_RATE : 0) +
129	  (isHighlyEnchanted(item) ? HIGH_ENCHANTMENT_SURCHARGE_RATE : 0);
130	
131	// Item-specific modifiers apply to the affected item's own base premium, not to
132	// the policy total — note that is the *ungrouped* base premium, so a cursed
133	// rune inside a block is surcharged on 25 G, not on a share of the block's 60.
134	const policyItemSurchargeTotal = (items: Item[]): number =>
135	  sum(
136	    items.map((item) => basePremiumOf(item.type) * itemSurchargeRate(item)),
137	  );
138	
139	const isLoyal = (customer: Customer): boolean =>
140	  customer.yearsWithMHPCO >= LOYALTY_THRESHOLD_YEARS;
141	
142	// Policy-wide rates are summed rather than compounded, so a loyal customer's
143	// first insurance is levied at -20 % + 10 % = -10 % of the policy base premium.
144	// Every quote after the customer's first is a follow-up contract; the
145	// first-insurance surcharge still applies to it, since each item in a quote is
146	// treated as a first insurance regardless of customer history.
147	const policyModifierRate = (customer: Customer, isFollowUp: boolean): number =>
148	  (isLoyal(customer) ? -LOYALTY_DISCOUNT_RATE : 0) +
149	  (isFollowUp ? -FOLLOW_UP_CONTRACT_DISCOUNT_RATE : 0) +
150	  FIRST_INSURANCE_SURCHARGE_RATE;
151	
152	const priceQuote = (
153	  step: QuoteStep,
154	  customer: Customer,
155	  isFollowUp: boolean,
156	): QuoteResult => {
157	  // Every modifier is a percentage of an *unmodified* base and they are all
158	  // summed, never compounded. Item surcharges are percentages of the affected
159	  // item's own base premium; policy-wide modifiers are percentages of the
160	  // policy base premium, which excludes those item surcharges. Summing the
161	  // rates before multiplying also keeps binary floating point out of trouble:
162	  // a compounded `base * (1 + rate)` chain drifts by ~1e-14, and Math.ceil
163	  // would turn that into a whole extra gold piece.
164	  const policyBase = policyBasePremium(step.items);
165	  const premiumBeforeFee =
166	    policyBase +
167	    policyItemSurchargeTotal(step.items) +
168	    policyBase * policyModifierRate(customer, isFollowUp);
169	
170	  // The fee is added after every percentage modifier, and only the final
171	  // premium is rounded — intermediates stay fractional.
172	  return { premium: Math.ceil(premiumBeforeFee + PROCESSING_FEE) };
173	};
174	
175	// A quote is a follow-up contract when the customer already holds one, i.e.
176	// when an earlier step in this scenario was itself a quote. Preceding claim
177	// steps do not make the next quote a follow-up.
178	const isFollowUpContract = (steps: StepInput[], index: number): boolean =>
179	  steps.slice(0, index).some(isQuoteStep);
180	
181	const DEDUCTIBLE_PER_DAMAGE = 100;
182	
183	const CAP_MULTIPLE_OF_INSURANCE_SUM = 2;
184	
185	// The insurance sum is the plain sum of the items' insurance values; the block
186	// discount applies to the premium only, never to the sum insured.
187	const insuranceSum = (items: Item[]): number =>
188	  sum(items.map((item) => insuranceValueOf(item.type)));
189	
190	// A policy pays out at most twice its insurance sum over its lifetime.
191	const policyCap = (items: Item[]): number =>
192	  CAP_MULTIPLE_OF_INSURANCE_SUM * insuranceSum(items);
193	
194	// Distinct from the premium-side high-enchantment *surcharge*, whose threshold
195	// is 5: this is a different rule that happens to key off the same attribute.
196	const HIGH_ENCHANTMENT_REIMBURSEMENT_THRESHOLD = 8;
197	
198	const HIGH_ENCHANTMENT_REIMBURSEMENT_RATE = 0.5;
199	
200	const FULL_REIMBURSEMENT_RATE = 1;
201	
202	const hasHighEnchantmentReimbursement = (item: Item): boolean =>
203	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_REIMBURSEMENT_THRESHOLD;
204	
205	// Each clause states the share of the damage it will reimburse; an item that
206	// trips no clause is reimbursed in full.
207	//
208	// The spec's second reimbursement clause — "damage to items made of dragon
209	// material is fully reimbursed" — is deliberately absent, not forgotten. It is
210	// unobservable here, on two counts:
211	//
212	//   1. It reimburses at FULL_REIMBURSEMENT_RATE, which is already the rate for
213	//      an item that trips no clause at all. On its own it changes nothing.
214	//   2. Where it competes with the high-enchantment clause, the spec says the
215	//      50 % rule wins (enchantment 9 + dragon → 400 G, same as enchantment 9
216	//      alone). So it cannot win a conflict either.
217	//
218	// No input the spec describes distinguishes an implementation with a dragon
219	// branch from this one, so `material` is not a field on `Item`. This stops
220	// holding the moment full reimbursement stops being the default — e.g. if a
221	// policy-wide co-payment is introduced — at which point the clause becomes
222	// observable and must be implemented.
223	const reimbursementRate = (item: Item): number =>
224	  hasHighEnchantmentReimbursement(item)
225	    ? HIGH_ENCHANTMENT_REIMBURSEMENT_RATE
226	    : FULL_REIMBURSEMENT_RATE;
227	
228	// A reimbursement clause reduces the damage amount; the deductible comes off
229	// whatever the clause leaves.
230	//
231	// `item` is optional only because a damage entry naming an uninsured item is
232	// not yet rejected — that is a pending error test. Until then such an entry is
233	// reimbursed in full, and this is the single place tolerating the gap.
234	const damagePayout = (damage: Damage, item: Item | undefined): number => {
235	  const rate =
236	    item === undefined ? FULL_REIMBURSEMENT_RATE : reimbursementRate(item);
237	
238	  return damage.amount * rate - DEDUCTIBLE_PER_DAMAGE;
239	};
240	
241	// The deductible applies once per damaged item, so each damage entry is
242	// reduced separately before the entries are summed. A damage entry names its
243	// item by type, so the clauses are read off the matching insured item.
244	const incidentPayout = (incident: Incident, policyItems: Item[]): number =>
245	  Math.floor(
246	    sum(
247	      incident.damages.map((damage) =>
248	        damagePayout(
249	          damage,
250	          policyItems.find((item) => item.type === damage.itemType),
251	        ),
252	      ),
253	    ),
254	  );
255	
256	// The cap is a lifetime budget for the policy, so a claim can pay out only what
257	// earlier claims against the same policy have left of it.
258	const settleClaim = (
259	  step: ClaimStep,
260	  policyItems: Item[],
261	  alreadyPaidOut: number,
262	): ClaimResult => {
263	  const remainingBefore = policyCap(policyItems) - alreadyPaidOut;
264	  const payout = Math.min(
265	    incidentPayout(step.incident, policyItems),
266	    remainingBefore,
267	  );
268	
269	  return { payout, remainingCap: remainingBefore - payout };
270	};
271	
272	const quoteStepAt = (steps: StepInput[], index: number): QuoteStep => {
273	  // `policy` is a step number in the scenario, so it indexes the full step
274	  // list — not a prefix of it.
275	  const step = steps[index];
276	  if (step === undefined || !isQuoteStep(step)) {
277	    throw new Error(`Claim references a step that is not a quote`);
278	  }
279	  return step;
280	};
281	
282	// The payouts made so far against each policy, keyed by the step index of the
283	// quote that created it. Claims consume their policy's cap as the scenario
284	// runs, so this has to be carried from each step to the next.
285	type PaidOutByPolicy = ReadonlyMap<number, number>;
286	
287	const paidOutOn = (paidOut: PaidOutByPolicy, policy: number): number =>
288	  paidOut.get(policy) ?? 0;
289	
290	const withPayoutRecorded = (
291	  paidOut: PaidOutByPolicy,
292	  policy: number,
293	  payout: number,
294	): PaidOutByPolicy =>
295	  new Map(paidOut).set(policy, paidOutOn(paidOut, policy) + payout);
296	
297	// Running a step yields its result *and* the cap ledger the next step must see.
298	// Pairing them is what lets a claim hand on the payout it just consumed without
299	// the caller having to re-derive the step's kind from its result.
300	type StepOutcome = { result: StepResult; paidOut: PaidOutByPolicy };
301	
302	const runStep = (
303	  step: StepInput,
304	  customer: Customer,
305	  steps: StepInput[],
306	  index: number,
307	  paidOut: PaidOutByPolicy,
308	): StepOutcome => {
309	  if (isQuoteStep(step)) {
310	    // A quote consumes no cap, so it passes the ledger on untouched.
311	    return {
312	      result: priceQuote(step, customer, isFollowUpContract(steps, index)),
313	      paidOut,
314	    };
315	  }
316	  if (isClaimStep(step)) {
317	    const result = settleClaim(
318	      step,
319	      quoteStepAt(steps, step.policy).items,
320	      paidOutOn(paidOut, step.policy),
321	    );
322	
323	    return {
324	      result,
325	      paidOut: withPayoutRecorded(paidOut, step.policy, result.payout),
326	    };
327	  }
328	  throw new Error(`Unsupported step op: ${step.op}`);
329	};
330	
331	// What the fold carries from step to step: the results so far, plus the cap
332	// ledger. Only `results` is part of the answer — `paidOut` is scaffolding, so
333	// this is deliberately not `ScenarioResults`.
334	type ScenarioProgress = {
335	  results: StepResult[];
336	  paidOut: PaidOutByPolicy;
337	};
338	
339	export const runScenario = (scenario: Scenario): ScenarioResults => {
340	  const { results } = scenario.steps.reduce<ScenarioProgress>(
341	    ({ results, paidOut }, step, index) => {
342	      const outcome = runStep(
343	        step,
344	        scenario.customer,
345	        scenario.steps,
346	        index,
347	        paidOut,
348	      );
349	
350	      return {
351	        results: [...results, outcome.result],
352	        paidOut: outcome.paidOut,
353	      };
354	    },
355	    { results: [], paidOut: new Map() },
356	  );
357	
358	  return { results };
359	};
